    private static byte[] bounded(byte[]b){if(b.length>MAX_BYTES)throw new IllegalArgumentException("OUTPUT_LIMIT_EXCEEDED");return b;}
    private static Map<String,Object>root(byte[]b,Set<String>keys){Map<String,Object>r=MigrationStrictJson.object(b,MAX_BYTES);exact(r,keys);return r;}
