    private static List<String>strings(Map<String,Object>m,String k){Object v=m.get(k);if(!(v instanceof List<?>l)||l.stream().anyMatch(x->!(x instanceof String)))throw new IllegalArgumentException(k);return l.stream().map(String.class::cast).toList();}
    private static<T extends Enum<T>>T value(Map<String,Object>m,String k,Class<T>type){try{return Enum.valueOf(type,string(m,k));}catch(RuntimeException e){throw new IllegalArgumentException(k,e);}}
    private static<T extends Enum<T>>T nullableEnum(Map<String,Object>m,String k,Class<T>type){String v=nullable(m,k);try{return v==null?null:Enum.valueOf(type,v);}catch(RuntimeException e){throw new IllegalArgumentException(k,e);}}
